        "action_cost": "r",
        "bulk": null,
        "category": "spell",
        "description": "<p>\"Déclencheur\" Un effet devrait vous infliger des dégâts d'acide, d'électricité, de feu ou de froid</p>\n<p>Vous avez l'habitude de mitiger les dégâts infligés par les bombes, les engins de siège et l'artillerie magique. Vous obtenez à votre choix une résistance 15 contre l'acide, l'électricité, le feu ou le froid de l'effet déclencheur. La résistance ne s'applique que contre les dégâts initiaux de l'effet déclencheur.</p>\n<p><div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'lEU3DH1tGjAigpEt'})\">Effet : Absorption d'énergie</div></p>\n<p>\"Intensifié (+1)\" La résistance augmente de 5.</p>",
