        "action_cost": "2",
        "bulk": null,
        "category": "spell",
        "description": "<p>Des ailes de cuir émergent de votre dos, vous conférant une Vitesse de vol de 18 mètres ou égale à votre Vitesse selon laquelle est la plus élevée. Si vous êtes toujours en train de voler lorsque la durée de ce sort s'achève, vous flottez jusqu'au sol, comme avec les effets du sort  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'TTwOKGqmZeKSyNMH'})\">Atterrissage en douceur</div> .</p>\n<p>\"Intensifié (8e)\" La durée passe à 10 minutes.</p>\n<p><div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'jy4edd6pvJvJgOSP'})\">Effet : Ailes de dragons</div></p>",
