        "description": "<p>Vous embellissez l'esprit de la cible, renforçant ses défenses mentales et soignant ses blessures. La cible regagne 1d10+4 Points de vie quand vous Lancez le sort et obtient un bonus de statut de +2 aux jets de sauvegarde contre les effets mentaux pendant la durée du sort.</p>\n<p><div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'nkk4O5fyzrC0057i'})\">Effet : Apaiser</div></p>\n<p>\"Intensifié (+1)\" Le montant de soins augmente de 1d10+4.</p>",
