        "description": "<p>Vous conjurez une créature qui possède le trait plante ou champignon et dont le niveau est de -1 pour qu'elle se batte pour vous.</p>\n<p>\"Intensifié\" Comme indiqué dans le trait  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': '8gcp880pEWZ9VPnF'})\">convocation</div> .</p>",
