        "category": "effect",
        "description": "<p>Accordé par  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'Gb7SeieEvd0pL2Eh'})\">Coup assuré</div> .</p>\n<p>La prochaine fois que vous effectuez un jet d'attaque avant la fin de votre tour, lancez l'attaque deux fois et utilisez le meilleur résultat. L'attaque ignore les pénalités de circonstances au jet d'attaque et vous n'avez pas besoin d'effectuer le test nu si la cible est Masquée ou Cachée.</p>",
