    "zR67Rt3UMHKC5evy": {
        "action_cost": "2",
        "bulk": null,
        "category": "spell",
        "description": "<p>Vous oscillez rapidement entre votre plan actuel et un autre. Vous obtenez une résistance 5 contre tous les dégâts (sauf de force). À la fin de chacun de vos tours, Vous vous téléportez automatiquement de 3 mètres dans une direction aléatoire déterminée par le MJ. Vous pouvez Maintenir le sort pour vous téléporter de cette manière.</p>\n<p><div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'ZlsuhS9J0S3PuvCO'})\">Effet : Osciller</div></p>\n<p>\"Intensifié (+2)\" La résistance augmente de 3</p>",
        "element_type": "SORT 4",
        "href": "/spells/zR67Rt3UMHKC5evy",
        "id": "zR67Rt3UMHKC5evy",
        "price": null,
        "required": [],
        "text": "Oscillation",
        "traits": [
            "Concentration",
            "Manipulation",
            "Téléportation"
        ]
    },
    "ffz6wlSMzhaDpjg6": {
        "action_cost": "1",
        "bulk": null,
        "category": "spell",
        "description": "<p>Avec une ondulation de terre, vous soulevez de petites barrières du sol. Le sol de la région devient un terrain difficile. La zone du sort est une  explosion de 1,50 mètre  si vous y consacrez 1 action pour la lancer, une  explosion de 3 mètres  si vous y consacrez 2 actions ou une  explosion de 4,50 mètres  si vous y consacrez 3 actions. Une créature peut Interagir pour supprimer les barrières dans une des cases qui lui est adjacente.</p>\n<p>\"Intensifié (4e)\" Vous tirez les barrières pour qu'elles flottent dans les airs, ce qui permet au sort de fonctionner comme un terrain difficile pour les créatures volantes.</p>",
        "element_type": "FOCALISÉ 1",
        "href": "/spells/ffz6wlSMzhaDpjg6",
        "id": "ffz6wlSMzhaDpjg6",
        "price": null,
        "required": [],
        "text": "Ouvrages de terre",
        "traits": [
            "Peu courant",
            "Concentration",
            "Terre",
            "Focalisation",
            "Manipulation",
            "Magicien"
        ]
    },
    "SjmKHgI7a5Z9JzBx": {
        "action_cost": "1",
        "bulk": null,
        "category": "action",
        "description": "<p>En utilisant votre corps, un levier ou un autre outil, vous tentez de forcer l'ouverture d'une porte, d'une fenêtre, d'un contenant ou d'une grille épaisse. Avec un résultat suffisamment élevé, vous pouvez même traverser des murs. Sans pied-de-biche, vous subissez une pénalité d'objet de -2 au test d' Athlétisme  si vous tentez d'Ouvrir de force quelque chose.</p>\n<p>\"Succès critique\" Vous ouvrez la porte, la fenêtre, le contenant ou la grille et pouvez éviter de l'endommager si vous le souhaitez.</p>\n<p>\"Succès\" Vous brisez la porte, la fenêtre, le contenant ou ouvrez la porte et il obtient l'état  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': '6dNUvdb1dhToNDj3'})\">Brisé</div> . Si c'est particulièrement robuste, le MJ pourrait lui faire subir des dégâts mais sans qu'il soit Brisé.</p>\n<p>\"Échec critique\" Votre tentative bloque la porte, la fenêtre, le contenant ou l'ouverture de la grille, imposant une pénalité de circonstances de -2 sur les futures tentatives pour l'Ouvrir de force.</p>\nOuvrir de force : exemples de tâches\n\n\"Inexpérimenté\" tissu, verre fin\n\"Qualifié\" glace, verre épais\n\"Expert\" porte en bois peu épais, herse en bois\n\"Maître\" porte en bois épais, herse en fer, barreau métallique\n\"Légendaire\" porte en pierre ou en fer",
        "element_type": null,
        "href": "/actions/SjmKHgI7a5Z9JzBx",
        "id": "SjmKHgI7a5Z9JzBx",
        "price": null,
        "required": [],
        "text": "Ouvrir de force",
        "traits": [
            "Attaque"
        ]
    },
    "vPWMEyVTreMOoFnm": {
        "action_cost": null,
        "bulk": null,
        "category": "spell",
        "description": "<p>Vous faites pousser un demi-plan extradimensionnel composé d'une demeure spacieuse dotée d'une unique entrée. L'entrée est reliée au plan où vous Lancez le sort en apparaissant où vous le souhaitez dans la portée du sort sous la forme d'un rectangle vertical translucide et scintillant de 1,50 mètre de large et de 3 mètres de hauteur. Vous désignez qui peut entrer quand vous lancez le sort. Une fois à l'intérieur, vous pouvez fermer l'entrée, la rendant invisible. Vous et les créatures désignées pouvez rouvrir la porte à volonté.</p>\n<p>À l'intérieur, le demi-plan ressemble à une demeure composé d'un magnifique vestibule et de nombreuses et somptueuses salles. Le manoir peut prendre toute configuration que vous imaginez lorsque vous Lancez le sort tant qu'il tient dans un espace de 12 mètres de large, 12 mètres de long et 9 mètres de hauteur. Tant que l'entrée de la demeure est fermée, les effets provenant de l'extérieur ne peuvent pas atteindre l'intérieur et vice versa, à l'exception de  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': '5bTt2CvYHPvaR7QQ'})\">Téléportation interplanaire</div>  qui peut être utilisée pour entrer dans la demeure.</p>\n<p>Un effectif allant jusqu'à 24 domestiques s'occupent de ceux qui se trouvent dans la demeure. Ils ressemblent au sbire créé par le sort  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'xqmHD8JIjak15lRk'})\">Sbire fantasmagorique</div>  bien qu'ils soient visibles avec un aspect que vous déterminez lors de l'incantation. La demeure contient un stock de nourriture suffisant pour fournir un banquet de neuf plats pour 150 personnes.</p>",
        "element_type": "SORT 7",
        "href": "/spells/vPWMEyVTreMOoFnm",
        "id": "vPWMEyVTreMOoFnm",
        "price": null,
        "required": [],
        "text": "Palais planaire",
        "traits": [
            "Peu courant",
            "Concentration",
            "Extradimensionnel",
            "Manipulation"
        ]
    },
