    "qsNeG9KZpODSACMq": {
        "action_cost": "2",
        "bulk": null,
        "category": "spell",
        "description": "<p>Vous obtenez un sixième sens qui vous avertit de tout danger susceptible de s'abattre sur la cible du sort. Si vous choisissez une créature autre que vous comme cible, vous créez un lien psychique entre vous par lequel vous l'avertissez du danger. Ce lien est un effet mental. En raison du nombre d'informations que ce sort vous demande de traiter, vous ne pouvez avoir qu'un seul sort <em>Prémonition</em> actif à la fois. Si vous lancez le sort de nouveau, la précédente incantation se termine. Tant que <em>Prémonition</em> fait effet, la cible obtient un bonus de statut de +2 aux jets d'initiative et n'est pas  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'AJh5ex99aV6VTggg'})\">Prise au dépourvu</div>  contre les créatures  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'VRSef5y1LmL2Hkjf'})\">Non détectées</div>  ou en cas de prise en tenaille. De plus, vous obtenez la réaction  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'VOEWhPQfN3lvHivK'})\">Prémonition</div></p>\n<p><div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'X9Na6IK8FSPcTuoc'})\">Effet : Prémonition</div></p>",
        "element_type": "SORT 9",
        "href": "/spells/qsNeG9KZpODSACMq",
        "id": "qsNeG9KZpODSACMq",
        "price": null,
        "required": [],
        "text": "Prémonition",
        "traits": [
            "Concentration",
            "Manipulation",
            "Mental",
            "Prédiction"
        ]
    },
    "QHFMeJGzFWj2QczA": {
        "action_cost": "1",
        "bulk": null,
        "category": "action",
        "description": "<p>\"Coût\" 1 fiole polyvalente</p>\n<p>\"Conditions\" Vous connaissez la formule de l'objet alchimique que vous créez, vous tenez ou portez du Matériel d'alchimiste et vous disposez d'une main libre.</p>\n<p>Vous concoctez rapidement une préparation à la durée de validité très courte. Vous créez un unique élixir ou outil alchimique de votre niveau ou moins sans avoir à dépenser le coût monétaire habituel en réactifs alchimiques et sans avoir à effectuer un test d'Artisanat. L'objet possède le trait imprégné mais il reste efficace seulement jusqu'à la fin de votre tour actuel.</p>",
        "element_type": null,
        "href": "/actions/QHFMeJGzFWj2QczA",
        "id": "QHFMeJGzFWj2QczA",
        "price": null,
        "required": [],
        "text": "Préparation rapide",
        "traits": [
            "Enquêteur",
            "Manipulation"
        ]
    },
    "fkDeKktdmbeplYRY": {
        "action_cost": "2",
        "bulk": null,
        "category": "spell",
        "description": "<p>Vous vous entourez d'une aura de splendeur surnaturelle, apparaissant comme un dieu ou un être similairement majestueux avec un aspect, des regalia et une iconographie de votre choix. Les cibles doivent tenter un jet de Volonté. Quelle que soit l'issue, la cible est alors temporairement immunisée pendant 1 minute.</p>\n<p>\"Succès critique\" La cible n'est pas affectée.</p>\n<p>\"Succès\" La cible doit vous rendre hommage à deux reprises. Rendre hommage nécessite que la cible dépense une action unique qui a soit le trait déplacement (lorsqu'elle s'incline), soit le trait manipulation (si elle présente quelque chose qu'elle tient). Elle doit rendre hommage au moins une fois à chacun de ses tours, si possible. Tant qu'elle est affectée, la cible est  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'AdPVz7rbaVSRxHFg'})\">Fascinée</div>  par votre présence et ne peut effectuer aucune action hostile à votre encontre.</p>\n<p>\"Échec\" La cible doit vous rendre hommage un total de six reprises.</p>\n<p>\"Échec critique\" Comme en cas d'échec mais la cible doit dépenser toutes ses actions pour vous rendre hommage et elle ne peut entreprendre aucune action tant que l'hommage n'est pas complètement rendu.</p>",
        "element_type": "SORT 9",
        "href": "/spells/fkDeKktdmbeplYRY",
        "id": "fkDeKktdmbeplYRY",
        "price": null,
        "required": [],
        "text": "Présence écrasante",
        "traits": [
            "Audible",
            "Concentration",
            "Mise hors de combat",
            "Manipulation",
            "Mental",
            "Visuel"
        ]
    },
