        "bulk": null,
        "category": "condition",
        "description": "<p>Vous disposez de moins d'actions. L'état Ralenti inclut une valeur. Lorsque vous regagnez des actions, réduisez la quantité d'actions que vous obtenez de la valeur de votre état Ralenti. Comme vous obtenez des actions au début de votre tour, vous ne perdez pas immédiatement des actions si vous obtenez cet état au cours de votre tour.</p>",
