    "G56DJkxlUjFv0C4Z": {
        "action_cost": "1",
        "bulk": null,
        "category": "spell",
        "description": "<p>Vous créez un fanal temporel en ayant l'intention d'y revenir si les choses tournent mal. Vous pouvez lancer <em>Repère temporel</em> seulement à votre tour. Conservez soigneusement trace de tout ce qui se produit durant le tour après que vous ayez lancé <em>Repère temporel</em>. À la fin de votre tour, vous pouvez choisir de revenir en arrière dans le temps juste après avoir lancé <em>Repère temporel</em>, en retirant tous les effets de votre tour depuis lors. Les malédictions, les pièges et les autres effets néfastes qui se produisent durant votre tour pourraient vous empêcher de retourner au repère s'ils sont assez puissants. Si vous avez subi n'importe quel effet nuisible durant votre tour après avoir lancé <em>Repère temporel</em>, pour revenir à votre repère, <em>Repère temporel</em> tente de contrer le test contre chacun de ces différents effets. En cas d'échec à l'un de ces tests, vous ne pouvez revenir en arrière. Après être revenu à votre <em>Repère temporel</em>, le sort se termine.</p>",
        "element_type": "SORT 7",
        "href": "/spells/G56DJkxlUjFv0C4Z",
        "id": "G56DJkxlUjFv0C4Z",
        "price": null,
        "required": [],
        "text": "Repère temporel",
        "traits": [
            "Manipulation"
        ]
    },
    "ljo9CEmnCMZXqfOQ": {
        "action_cost": "2",
        "bulk": null,
        "category": "spell",
        "description": "<p>Vous sentez que cet endroit aspire à se débarrasser des chaînes de la civilisation. Vous tentez de rendre à la zone de l'explosion son état naturel, en retirant tous les objets et bâtiments artificiels et en encourageant la croissance des plantes sur le sol qui reste. Les créatures ne sont pas affectées, à moins qu'elles ne soient prises dans l'effondrement de structures.</p>\n<ul><li>\"Sol\" Tout le sol dans la zone devient un terrain très difficile pendant 1 round.</li><li>\"Objets\" Tout objet non tenu de 4 Encombrements ou moins est détruit, quelle que soit sa Solidité, à moins que ce ne soit un artefact ou tout autant difficile à détruire.</li><li>\"Plantes\" Les plantes dans la zone sont plus saines et plus fructifères pendant 1 an.</li><li>\"Structures\" Les structures à portée sont secouées et pourraient s'effondrer, comme si elles étaient affectées par  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'x7SPrsRxGb2Vy2nu'})\">Tremblement de terre</div> .</li></ul>",
        "element_type": "SORT 7",
        "href": "/spells/ljo9CEmnCMZXqfOQ",
        "id": "ljo9CEmnCMZXqfOQ",
        "price": null,
        "required": [],
        "text": "Restaurer le sol",
        "traits": [
            "Peu courant",
            "Concentration",
            "Terre",
            "Manipulation"
        ]
    },
    "ziHDISWkFSwz3pmn": {
        "action_cost": "2",
        "bulk": null,
        "category": "spell",
        "description": "<p>Avec une vague d'énergie guérisseuse, vous repoussez une affliction menaçant la cible et lui accordez un petit montant de soins. La cible récupère 3d8 Points de vie.</p>\n<p>Vous tentez de contrer n'importe quelle affliction dont vous savez que la cible souffre, suspendant ses effets pendant 1 heure sur un succès au lieu de l'en délivrer.</p>\n<p>La cible est alors temporairement immunisée à <em>Retarder l'affliction</em> pendant 1 journée. Vous n'avez pas besoin d'avoir identifié le nom de l'affliction particulière, mais vous avez besoin d'en être conscient. Par exemple, vous ne pourriez retarder un poison ingéré durant sa période d'incubation à moins d'être conscient de l'existence du poison.</p>\n<p>\"Intensifié (+1)\" La cible récupère 1d8 Points de vie supplémentaires et vous pouvez tenter de suspendre une affliction supplémentaire.</p>",
        "element_type": "FOCALISÉ 3",
        "href": "/spells/ziHDISWkFSwz3pmn",
        "id": "ziHDISWkFSwz3pmn",
        "price": null,
        "required": [],
        "text": "Retarder l'affliction",
        "traits": [
            "Peu courant",
            "Concentration",
            "Focalisation",
            "Guérison",
            "Manipulation",
            "Oracle",
            "Vitalité"
        ]
    },
