        "action_cost": "1",
        "bulk": null,
        "category": "action",
        "description": "<p>Vous étiez  <div class=\"gs-link-information\" onclick=\"CONTROLLER.Main.doActionAfter('event__show_information', {'param__object__uuid': 'j91X7x0XSomq8d60'})\">À terre</div>  et vous Vous relevez.</p>",
